--
-- Table structure for table `refund_items`
--

DROP TABLE IF EXISTS `refund_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sale_id` int NOT NULL,
  `sale_item_id` int NOT NULL,
  `product_id` int NOT NULL,
  `product_name_snapshot` varchar(200) NOT NULL,
  `quantity_refunded` int NOT NULL,
  `price_at_sale` decimal(10,2) NOT NULL,
  `refund_subtotal` decimal(10,2) NOT NULL,
  `refunded_by` int NOT NULL COMMENT 'users.id of staff who processed refund',
  `reason` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `return_condition` varchar(20) DEFAULT 'resellable',
  `refund_method` varchar(10) DEFAULT NULL,
  `refund_event_id` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_refund_items_sale_id` (`sale_id`),
  KEY `idx_refund_items_sale_item_id` (`sale_item_id`),
  KEY `refund_items_ibfk_product` (`product_id`),
  KEY `refund_items_ibfk_user` (`refunded_by`),
  CONSTRAINT `refund_items_ibfk_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `refund_items_ibfk_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE,
  CONSTRAINT `refund_items_ibfk_sale_item` FOREIGN KEY (`sale_item_id`) REFERENCES `sale_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `refund_items_ibfk_user` FOREIGN KEY (`refunded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

